        tuple[dict, torch.Tensor, torch.Tensor]:
            dict: Output gaussian
                mean (torch.Tensor): (bs, *, out_channels, h, w)
                var (torch.Tensor): (bs, *, 1, h, w)
            torch.Tensor: (bs, *, num_gaussians, out_channels, h, w)
