\begin{equation*}
    \begin{aligned}
    &= \frac{\left( (1 - \alpha_{s}) \rvm \right)^{\omega+1} + \left((\alpha_{s} - \alpha_t) \vmu_{\theta}^{\cat}(\rvx_t, \rvy, t) \right)^{\omega+1}}
