def random_masking_uniform(self, x, orders):
    bsz, seq_len, embed_dim = x.shape
    # Uniform random masking: each token is independently masked with p=0.5 (for NLL computation)
    mask_prob = 0.5
    device = x.device
    mask = (torch.rand(bsz, seq_len, device=device) < mask_prob).float()
    # Now, rearrange mask according to random orders so that mask's positions are consistent with `orders`.
    sorted_orders = torch.argsort(orders, dim=-1)
    mask = torch.scatter(torch.zeros_like(mask), dim=-1, index=sorted_orders, src=mask)
    return mask
