            cur_patches[mask_to_pred.nonzero(as_tuple=True)] = sampled_patches.to(cur_patches.dtype)
            patches = cur_patches.clone()

            # visualize generation process for colab
            if visualize:
                visualize_patch(self.unpatchify(patches))

