\title{Transformers without Normalization}

\author[1,2]{Jiachen Zhu}
\author[1]{Xinlei Chen}
\author[3]{Kaiming He}
\author[1,2]{Yann LeCun}
\author[1,4,\dagger]{Zhuang Liu}


\affiliation[1]{FAIR, Meta}
